/// Step tabs: dots on a connecting line, labels under the dots. Completed
/// steps show a white check in a filled blue circle, the current step is a
/// filled blue dot, future steps are hollow.
class _Steps extends StatelessWidget {
  const _Steps({required this.page, required this.labels});

  final int page;
  final List<String> labels;

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final w = constraints.maxWidth;
        const dot = 18.0;
        final seg = w / labels.length;
        return SizedBox(
          height: 44,
          child: Stack(
            children: [
              Positioned(
                left: seg / 2,
                right: seg / 2,
                top: dot / 2 - 1,
                child: Container(height: 2, color: _onbBorder(context)),
              ),
              Row(
                children: [
                  for (var i = 0; i < labels.length; i++)
                    Expanded(
                      child: Column(
                        children: [
                          Container(
                            width: dot,
                            height: dot,
                            decoration: BoxDecoration(
                              shape: BoxShape.circle,
                              color: i <= page ? _kPrimary : _onbCard(context),
                              border: Border.all(
                                color: i <= page
                                    ? _kPrimary
                                    : _onbBorder(context),
                                width: 2,
                              ),
                            ),
                            child: i < page
                                ? const Icon(
                                    Icons.check,
                                    size: 11,
                                    color: Colors.white,
                                  )
                                : null,
                          ),
                          const SizedBox(height: 6),
                          // Long labels ("Make it yours") shrink to fit
                          // the narrower 5-step segments.
                          Flexible(
                            child: FittedBox(
                              fit: BoxFit.scaleDown,
                              child: Text(
                                labels[i],
                                style: TextStyle(
                                  fontSize: 11,
                                  fontWeight: i == page
                                      ? FontWeight.w700
                                      : FontWeight.w500,
                                  color: i == page
                                      ? _onbPrimary(context)
                                      : _onbGrayLight(context),
                                ),
                              ),
                            ),
                          ),
                        ],
                      ),
                    ),
                ],
              ),
            ],
          ),
        );
      },
    );
  }
}

