class _Footer extends StatelessWidget {
  const _Footer({
    required this.page,
    required this.pageCount,
    required this.wide,
    required this.primaryLabel,
    required this.onPrimary,
    required this.onBack,
    this.primaryEnabled = true,
  });

  final int page;
  final int pageCount;
  final bool wide;
  final String primaryLabel;
  final VoidCallback onPrimary;
  final VoidCallback? onBack;

  /// False greys out the primary button (mandatory provider step).
  final bool primaryEnabled;

  @override
  Widget build(BuildContext context) {
    final counter = Text(
      '${page + 1} of $pageCount',
      style: TextStyle(
        fontSize: 12.5,
        fontWeight: FontWeight.w600,
        color: _onbInk(context),
      ),
    );
    final back = TextButton(
      onPressed: onBack,
      child: Text(
        'Back',
        style: TextStyle(
          fontSize: 13.5,
          color: _onbGray(context),
          fontWeight: FontWeight.w500,
        ),
      ),
    );
    const privacy = _PrivacyLink();
    if (wide) {
      return Padding(
        padding: const EdgeInsets.fromLTRB(28, 10, 28, 22),
        child: Stack(
          alignment: Alignment.center,
          children: [
            Row(
              children: [
                counter,
                const SizedBox(width: 14),
                _ProgressBar(fraction: (page + 1) / pageCount, width: 200),
                const Spacer(),
                if (onBack != null) ...[back, const SizedBox(width: 16)],
                SizedBox(
                  width: 250,
                  child: _PrimaryButton(
                    label: primaryLabel,
                    onTap: onPrimary,
                    enabled: primaryEnabled,
                  ),
                ),
              ],
            ),
            // Pinned to the footer center: the Back button appearing on
            // later pages must not shift the link horizontally.
            const Center(child: privacy),
          ],
        ),
      );
    }
    return Padding(
      padding: const EdgeInsets.fromLTRB(20, 8, 20, 12),
      child: Column(
        children: [
          Text(
            '${page + 1} of $pageCount',
            style: const TextStyle(
              fontSize: 12.5,
              fontWeight: FontWeight.w600,
              color: _kPrimary,
            ),
          ),
          const SizedBox(height: 10),
          Row(
            children: [
              if (onBack != null) ...[back, const SizedBox(width: 12)],
              Expanded(
                child: _PrimaryButton(
                  label: primaryLabel,
                  onTap: onPrimary,
                  showArrow: false,
                  enabled: primaryEnabled,
                ),
              ),
            ],
          ),
          privacy,
        ],
      ),
    );
  }
}

