    ),
  );
}

String _tileLabel(String key) {
  if (key == LauncherLayoutStore.settingsKey) {
    return context.l10n.settingsTitle;
  }
  if (key == LauncherLayoutStore.filesKey) {
    return context.l10n.chatFilesTooltip;
