  String filename(CodeConfig config) {
    final basename = this.basename;
    return switch (config.targetOS) {
      OS.windows => '$basename.dll',
      OS.iOS || OS.macOS => 'lib$basename.dylib',
      OS.android || OS.linux || _ => 'lib$basename.so',
    };
  }
}

