  SessionKeysStore? keysStore,
  int initialPage = 0,
  void Function({required bool skipped})? onFinished,
  ProviderRegistry? registry,
  LastConnectionStore? lastConnectionStore,
}) {
  return tester.pumpWidget(
    MaterialApp(
