    return switch (config.targetOS) {
      OS.windows => windows,
      OS.macOS => macos,
      OS.linux => linux,
      OS.iOS when config.iOS.targetSdk == IOSSdk.iPhoneOS => ios,
      OS.iOS when config.iOS.targetSdk == IOSSdk.iPhoneSimulator =>
        iosSimulator,
      OS.android => android,

