  sqlite3mc,

  /// SQLCipher build, with sources taken from https://github.com/sqlcipher/sqlcipher.
  sqlcipher;

  String get basename => switch (this) {
    LibraryType.sqlite3 => 'sqlite3',
    LibraryType.sqlite3mc => 'sqlite3mc',
    LibraryType.sqlcipher => 'sqlcipher',
